Method.Implementation:

	 try{
		 do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.mmi.CdrMmiAdd).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

 #dim status as %Status
 set status = $$$OK
 $$$TRACE("Inside OnMessage method")	 

 try {		 

    if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Cdr-Adt-Cff-ADD", "AddMMI failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
			return status
		}
 	}

	set result = ..objCdrTuxService.addMMI(pRequest.RawContent)
	$$$TRACE("Call Response: " _ result)

	if ($L(result) > 1){
		$$$TRACE("AddMmi Sucessful!!! MMI#: " _ result)
		set pResponse = ##class(Ens.StringResponse).%New("")
	    set pResponse.StringValue = result
	}else{		
		set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Cdr-Adt-Cff_Add", "MMIAdd failed. MMI#: " _result)			
	}

 } catch err {	 
 	 Set status = ..ExceptionHandler(err, "OnMessage")
 } 
 return status
